import { uniqueStrings } from './unique_repeat.mjs';
import assert from 'node:assert';

// Basic dedup preserving order
assert.deepStrictEqual(
  uniqueStrings(['a', 'b', 'a', 'c', 'b']),
  ['a', 'b', 'c']
);

// Case-sensitive: upper/lower remain distinct
assert.deepStrictEqual(
  uniqueStrings(['a', 'A', 'a', 'A']),
  ['a', 'A']
);

// Whitespace not trimmed
assert.deepStrictEqual(
  uniqueStrings([' x', 'x', ' x']),
  [' x', 'x']
);

// Empty input
assert.deepStrictEqual(uniqueStrings([]), []);

// Input not mutated
const input = ['a', 'b', 'a'];
const snapshot = [...input];
uniqueStrings(input);
assert.deepStrictEqual(input, snapshot);

// Original spelling preserved
assert.deepStrictEqual(
  uniqueStrings(['Hello', 'hello', 'Hello']),
  ['Hello', 'hello']
);

console.log('All checks passed.');
"

